import React, { useState } from 'react';
import { playerInfo } from './gameState';
import './GameBoard.css';

export default function GameBoard({ state: s, profiles, meeting, busy }) {
  const [selected, setSelected] = useState(null);
  const [tab, setTab] = useState('courts');
  const waiting = [...s.priorityCarry, ...s.participants];
  const allPlayers = [...waiting, ...s.teamQueue.flat(), ...s.courts.flatMap(c => c.team || [])];
  const uniquePlayers = [...new Set(allPlayers)];
  const countGender = gender => uniquePlayers.filter(key => playerInfo(key, profiles).gender === gender).length;
  function place(target) { if (!busy && selected) { s.movePlayer(selected, target); setSelected(null); } }
  function player(key, source, target) {
    const p = playerInfo(key, profiles);
    const active = selected?.name === key;
    return <button type="button" key={key} className={`operator-player ${active ? 'picked' : ''}`} disabled={busy} aria-pressed={active} onClick={() => {
      if (active) setSelected(null);
      else if (selected && target) place(target);
      else setSelected({ ...source, name: key });
    }}><span className={`gender-dot ${p.gender === '여성' ? 'female' : p.gender === '남성' ? 'male' : ''}`}>{p.gender === '여성' ? '여' : p.gender === '남성' ? '남' : '?'}</span><span className="player-label"><strong>{p.name}{Object.values(profiles).filter(info => info.name === p.name).length > 1 && <span className="name-id"> · {p.user_id?.slice(0, 8)}</span>}</strong><small>{p.gender || '성별 미등록'} · {s.playedCount[key] || 0}경기</small></span>{active && <span className="picked-mark">✓</span>}</button>;
  }
  return <main className="operator"><section className="operator-hero"><div><span className="eyebrow">MATCH CONTROL</span><h2>오늘의 경기 운영</h2><p>{meeting.location} · {new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', month: 'long', day: 'numeric', weekday: 'short' }).format(new Date(meeting.starts_at))}</p></div><span className="operator-live">● 운영 중</span></section>
    <div className="operator-stats"><div><span>전체 인원</span><strong>{uniquePlayers.length}<small>명</small></strong><p>남 {countGender('남성')} · 여 {countGender('여성')}</p></div><div><span>진행 중</span><strong>{s.courts.filter(c => c.team?.length).length}<small>코트</small></strong><p>사용 가능 {s.courts.length - s.disabledCourtsOnce.length}코트</p></div><div><span>경기 대기</span><strong>{waiting.length}<small>명</small></strong><p>대기 팀 {s.teamQueue.length}팀</p></div></div>
    <section className="operator-controls"><div><h3>다음 경기를 준비하세요</h3><p>잔여 인원 우선 배정 · 경기 수를 고려한 자동 편성</p></div><button disabled={busy || waiting.filter(p => !s.restOnce.includes(p)).length < 4} onClick={() => { setSelected(null); s.handleMakeTeams(); setTab('courts'); }}>🏸 팀 편성하기</button></section>
    <div className="operator-settings"><label htmlFor="operator-court-count">코트 수</label><select id="operator-court-count" value={s.courtCountInput} disabled={busy} onChange={e => s.setCourtCountInput(e.target.value)}>{Array.from({ length: 32 }, (_, i) => <option key={i + 1} value={String(i + 1)}>{i + 1}개</option>)}</select><button className="quiet" disabled={busy} onClick={() => { setSelected(null); s.applyCourtCount(); }}>적용</button><span>선수를 선택하고 이동할 자리 또는 교체할 선수를 누르세요.</span></div>
    {selected && <div className="operator-selection" role="status"><span><strong>{playerInfo(selected.name, profiles).name}</strong> 선택됨 · 이동할 곳을 눌러주세요</span><button className="quiet" onClick={() => setSelected(null)}>선택 취소</button></div>}
    <nav className="operator-tabs" aria-label="경기 운영 보기">{[['courts', `진행 코트 ${s.courts.length}`], ['waiting', `대기 인원 ${waiting.length}`], ['teams', `대기 팀 ${s.teamQueue.length}`]].map(([key, label]) => <button key={key} className={tab === key ? 'active' : ''} aria-pressed={tab === key} onClick={() => setTab(key)}>{label}</button>)}</nav>
    <div className="operator-layout"><section aria-label="진행 코트" className={`operator-courts ${tab === 'courts' ? 'mobile-visible' : ''}`}><div className="operator-section-title"><h3>진행 코트</h3><span>경기 종료 시 대기 팀 자동 입장</span></div><div className="operator-court-grid">{s.courts.map(c => {
      const disabled = s.disabledCourtsOnce.includes(c.id);
      return <article key={c.id} className={`operator-court ${disabled ? 'court-disabled' : ''}`}><header><input aria-label={`코트 ${c.id} 이름`} value={c.name} maxLength={30} disabled={busy} onChange={e => s.handleRenameCourt(c.id, e.target.value)} /><span>{disabled ? '사용 중지' : c.team?.length ? '경기 중' : '입장 대기'}</span></header><div className="operator-lines"><div className="court-half">{[0,1].map(i => c.team?.[i] ? player(c.team[i], { from: 'court', courtId: c.id, memberIndex: i }, { type: 'court', courtId: c.id, memberIndex: i }) : <button className="empty-slot" key={i} disabled={!selected || disabled || busy} onClick={() => place({ type: 'court', courtId: c.id })}>+ 선수 배치</button>)}</div><div className="court-net"><span>VS</span></div><div className="court-half">{[2,3].map(i => c.team?.[i] ? player(c.team[i], { from: 'court', courtId: c.id, memberIndex: i }, { type: 'court', courtId: c.id, memberIndex: i }) : <button className="empty-slot" key={i} disabled={!selected || disabled || busy} onClick={() => place({ type: 'court', courtId: c.id })}>+ 선수 배치</button>)}</div></div><div className="court-actions"><button className="quiet" disabled={busy} onClick={() => { setSelected(null); s.toggleDisableCourtOnce(c.id); }}>{disabled ? '코트 사용' : '사용 중지'}</button><button disabled={busy || !c.team?.length} onClick={() => { setSelected(null); s.handleFinishCourt(c.id); }}>경기 종료</button></div></article>;
    })}</div></section>
    <aside className="operator-sidebar"><section aria-label="경기 대기 인원" className={`operator-waiting ${tab === 'waiting' ? 'mobile-visible' : ''}`}><div className="operator-section-title"><h3>대기 인원 <span>{waiting.length}</span></h3><button className="quiet" disabled={!selected || busy} onClick={() => place({ type: 'participants' })}>대기로 이동</button></div>{!waiting.length && <p className="operator-empty">모든 참석자가 배정됐습니다.<br />경기 종료 후 대기 인원으로 돌아옵니다.</p>}{waiting.map(key => { const priority = s.priorityCarry.includes(key); return <div key={key} className="waiting-row">{player(key, { from: priority ? 'priority' : 'participants', fromIndex: (priority ? s.priorityCarry : s.participants).indexOf(key) })}<div className="waiting-tags">{priority && <span>우선 배정</span>}<button className={`quiet ${s.restOnce.includes(key) ? 'resting' : ''}`} disabled={busy} aria-label={`${playerInfo(key, profiles).name} 한 번 쉬기`} aria-pressed={s.restOnce.includes(key)} onClick={() => s.handleRestOnce(key)}>{s.restOnce.includes(key) ? '쉬는 중' : '한 번 쉬기'}</button><button className="quiet exclude-player" disabled={busy} aria-label={`${playerInfo(key, profiles).name} 경기 제외`} onClick={() => { setSelected(null); s.handleExcludePlayer(key); }}>삭제</button></div></div>; })}</section>
    {s.excludedPlayers?.length > 0 && <details className="excluded-players"><summary>경기 제외 · {s.excludedPlayers.length}명</summary><p>이번 모임의 경기에서 제외된 회원입니다.</p>{s.excludedPlayers.map(key => <div key={key}><span>{playerInfo(key, profiles).name}</span><button className="quiet" disabled={busy} aria-label={`${playerInfo(key, profiles).name} 다시 참여`} onClick={() => s.handleRestorePlayer(key)}>다시 참여</button></div>)}</details>}
    <section className={`operator-teams ${tab === 'teams' ? 'mobile-visible' : ''}`}><div className="operator-section-title"><h3>대기 팀 <span>{s.teamQueue.length}</span></h3></div>{!s.teamQueue.length && <p className="operator-empty">팀을 편성하면 빈 코트부터 배정하고<br />남은 팀은 여기에 대기합니다.</p>}{s.teamQueue.map((team, ti) => <article className="queued-team" key={ti}><h4><span>{String(ti + 1).padStart(2, '0')}</span> 다음 입장{ti ? ` · ${ti + 1}순위` : ''}</h4><div>{team.map((key, mi) => player(key, { from: 'queue', teamIndex: ti, memberIndex: mi }, { type: 'queue', teamIndex: ti, memberIndex: mi }))}</div>{team.length < 4 && <button className="quiet" disabled={!selected || busy} onClick={() => place({ type: 'queue', teamIndex: ti })}>+ 선수 추가</button>}</article>)}</section></aside></div>
  </main>;
}
